INSERT INTO `blogs` (`id`, `title`, `description`, `content`, `thumbnail`, `slug`, `timestamp`) VALUES
(15, '7 نوشیدنی گرم و دمنوش مناسب فصل پاییز', '<p>دمنوش پاییزی دمنوش ها از گیاهان دارویی گرفته می شوند که برای سلامتی بسیار مفید هستند. با وارد شدن به فصل پاییز و شروع شدن سرما و احتمال بالارفتن مریضی ها،یکی از سالم ترین روش های تقویت سیس', '<h2>دمنوش پاییزی</h2>\n<p>دمنوش ها از گیاهان دارویی گرفته می شوند که برای سلامتی بسیار مفید هستند. با وارد شدن به فصل پاییز و شروع شدن سرما و احتمال بالارفتن مریضی ها،یکی از سالم ترین روش های تقویت سیستم ایمنی استفاده از دمنوش ها است. دمنوش ها خواص زیادی از جمله تقویت سیستم ایمنی، جلوگیری و بهبود سرماخوردگی،رفع مشکلات گوارشی و تقویت معده را دارند.<br />\nدمنوش های گیاهی فاقد کافئین هستند و یکی از بهترین روش ها برای از بین بردن خستگی های روزانه هستند که در ادامه تعدادی از دمنوش های مناسب فصل پاییز را معرفی میکنیم.</p>\n<div dir=\"auto\">	<div id=\"the-content-products-swiper\">\r\n		<div class=\"swiper products-swiper\">\r\n			<div class=\"swiper-wrapper\">\r\n				<div class=\"swiper-slide\"><div>\r\n    \r\n    \r\n                </div>\r\n                    </div>\r\n\r\n        <div class=\"grid gap-1 bg-white z-10 relative\">\r\n            <a href=\"https://infinitycolor.co/product/%d8%b4%d9%88%d9%85%db%8c%d8%b2-%d9%be%d8%b1%db%8c-%d9%86%d8%a7%d8%b2-c00484/\" class=\"my-2 max-sm:text-xs max-sm:text-ellipsis max-sm:whitespace-nowrap max-sm:overflow-hidden\">\r\n                شومیز پری ناز C00484            </a>\r\n            <div class=\"flex justify-end gap-1 max-sm:text-xs\">\r\n                                    <span class=\"no-currency\">\r\n                                            </span>\r\n                    <span class=\"woocommerce-Price-amount amount\"><bdi>1,119,000&nbsp;<span class=\"woocommerce-Price-currencySymbol\">تومان</span></bdi></span>                            </div>\r\n        </div>\r\n\r\n    </div>\r\n</div></div><div class=\"swiper-slide\"><div>\r\n    \r\n    \r\n                </div>\r\n                    </div>\r\n\r\n        <div class=\"grid gap-1 bg-white z-10 relative\">\r\n     