INSERT INTO `products` (`id`, `name`, `description`, `price`, `discount`, `slug`, `timestamp`) VALUES
(116409, 'کیسه خواب جانگل کینگ CY-201701', '<h2 style=\"text-align: justify\">کیسه خواب کوهنوردی حانگل کینگ</h2>\n<p style=\"text-align: justify\">خوابیدن در طبیعت و کمپ زدن یکی از لذت بخش ترین کارهایی است که هر فرد در طول سفر خود به طبیعت ', 303896, 303896, '116409-کیسه-خواب-جانگل-کینگ-CY-201701', '1756018767'),
(116605, 'کیسه خواب دیزرت اند فاکس', '<h2 style=\"text-align: justify\">کیسه خواب طبیعت گردی دیزرت اند فاکس</h2>\n<p style=\"text-align: justify\">برای لذت بردن از سفر خود به طبیعت نیاز به وسیله هایی متفاوتی وجود دارد. وسیله هایی که م', 545168, 408876, '116605-کیسه-خواب-دیزرت-اند-فاکس', '1756018767'),
(138766, 'کیسه خواب نیچرهایک  U150', '<h2 style=\"text-align: justify\">کیسه خواب طبیعت گردی Naturehike U150</h2>\n<p style=\"text-align: justify\">این واقعیت غیر قابل انکار است که اگر یک کوهنورد حرفه ای و یا یک طبیعت گرد آماتور باشید', 594090, 445567, '138766-کیسه-خواب-نیچرهایک--U150', '1756018767'),
(240207, 'مانتو لینن زنانه 316127', '<h2>مانتو زنانه</h2>\n<p>مانتو ها امروزه یکی از پرکاربردترین پوشش های خانم هاست. مهم است که هنگام خرید مانتو زنانه بدانیم چه فاکتور ها و ویژگی هایی دارد.</p>\n<p>این محصول، یک مانتوی تک رنگ شیر', 565038, 423778, '240207-مانتو-لینن-زنانه-316127', '1756018767'),
(445266, 'تیشرت طرح دار زنانه پنبه 3026', '<h2>تیشرت زنانه</h2>\n<p>این محصول یک تیشرت زنانه راحت، با <strong>یقه ی گرد</strong> است. جنس آن از پارچه ی <strong>صد درصد پنبه</strong> است و روی آن <strong>طرح چاپی</strong> وجود دارد.</p>', 566577, 424932, '445266-تیشرت-طرح-دار-زنانه-پنبه-3026', '1756018767'),
(445332, 'بلوزابروبادی زنانه 304400', '<h2>بلوز زنانه طرح دار</h2>\n<p>یکی از پرطرفدار ترین پوشش ها در میان خانم ها بلوز ها و شومیز ها هستند. بلوز زنانه چه به صورت اسپرت و راحتی و چه به صورت رسمی و مجلسی همواره مورد توجه خانم ها بو', 187305, 187305, '445332-بلوزابروبادی-زنانه-304400', '1756018767'),
(445444, 'پیراهن مردانه طرح دار 4106', '<h2>پیراهن مردانه طرح دار</h2>\n<p>یکی از رایج ترین و پرطرفدارترین لباس های مردانه، پیراهن های مردانه می باشند.</p>\n<p>این محصول یک پیراهن <strong>آستین کوتاه</strong> مردانه طرح دار و بسیاری ', 447181, 447181, '445444-پیراهن-مردانه-طرح-دار-4106', '1756018767'),
(445445, 'تیشرت طرح دار مردانه 2491', '<h2 style=\"text-align: justify\"><b>تیشرت مردانه طرح دار</b></h2>\n<p>در فصل گرم سال، تیشرت مردانه یکی از انتخاب های پرطرفدار در بین آقایان می باشد.</p>\n<p style=\"text-align: justify\">جنس این ت', 143987, 143987, '445445-تیشرت-طرح-دار-مردانه-2491', '1756018767'),
